     2	export function readLimit(raw?: string): number {
     3	  return Number(raw) || 3;
     4	}
     5	export default async function runQueue(
     6	  jobs: Job[], rawLimit: string | undefined, save: (job: Job) => Promise<void>,
     7	): Promise<void> {
     8	  const selected = jobs.sort((a, b) => a.priority - b.priority).slice(0, readLimit(rawLimit));
     9	  selected.forEach(async (job) => { await save(job); });
