/bin/zsh -lc "/opt/homebrew/bin/node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import runQueue, {readLimit} from './dist/queue.js';
import {submit} from './dist/caller.js';
const jobs = () => [{id:'a', priority:20}, {id:'b', priority:2}, {id:'c', priority:10}];
assert.equal(readLimit('0'),3);
const paused=[];
assert.equal(await submit(jobs(), async j=>{paused.push(j.id);}), 'finished');
assert.deepEqual(paused,['b','c','a']);
console.log('Paused caller: returned finished and started saves:', paused);
const owned=jobs();
await runQueue(owned,'2',async()=>{});
assert.deepEqual(owned.map(j=>j.id),['b','c','a']);
console.log('Caller array mutated:', owned.map(j=>j.id));
const started=[], completed=[], releases=[];
await runQueue(jobs(),'2',j=>{started.push(j.id);return new Promise(resolve=>releases.push(()=>{completed.push(j.id);resolve();}));});
assert.deepEqual(started,['b','c']);
assert.deepEqual(completed,[]);
console.log('Queue resolved with pending saves:', {started,completed});
releases.forEach(release=>release());
const order=[];
await runQueue(jobs(),'3',async j=>{order.push(j.id);});
assert.deepEqual(order,['b','c','a']);
console.log('Save order for all selected jobs:', order, '(input order: a,b,c)');
const failure=new Error('save failed');
const unhandled=[];
process.on('unhandledRejection',e=>unhandled.push(e));
const failureStarts=[];
await runQueue(jobs(),'3',async j=>{failureStarts.push(j.id);throw failure;});
await new Promise(resolve=>setImmediate(resolve));
assert.deepEqual(failureStarts,['b','c','a']);
assert.equal(unhandled.length,3);
assert.ok(unhandled.every(e=>e===failure));
console.log('Save failures: queue fulfilled, later saves started:',failureStarts,'unhandled rejections:',unhandled.length);
NODE"

